import ast
import re
import os

class SQLiSinkFinder(ast.NodeVisitor):
    """Finds likely SQL-injection sinks: string-formatted query construction."""

    # Keywords that strongly suggest a SQL query
    SQL_KEYWORDS = (
        "SELECT", "INSERT", "UPDATE", "DELETE", "DROP", "CREATE",
        "ALTER", "TRUNCATE", "REPLACE", "WHERE", "FROM", "INTO",
    )

    def __init__(self):
        self.results = []  # list of (filename, lineno, code)

    def visit_BinOp(self, node):
        # Detect "SELECT * FROM x WHERE id = " + user_input
        if isinstance(node.op, (add := __import__("operator").add)):
            self._check_binop(node)
        self.generic_visit(node)

    def visit_Call(self, node):
        # Detect cursor.execute("... %s" % var) or execute(sql % {...})
        self._check_call(node)
        self.generic_visit(node)

    def _is_sql_string(self, s):
        if not isinstance(s, str):
            return False
        return any(kw in s.upper() for kw in self.SQL_KEYWORDS)

    def _check_binop(self, node):
        left = node.left
        right = node.right
        # One side is a string literal with SQL keywords, other is a variable/expr
        for literal, other in ((left, right), (right, left)):
            if isinstance(literal, ast.Constant) and isinstance(literal.value, str):
                if self._is_sql_string(literal.value):
                    self._record(node, f"{literal.value!r} + {ast.unparse(other)}")
                    return

    def _check_call(self, node):
        # Look for .execute(...) / .executemany(...) / .executescript(...)
        func = node.func
        if not isinstance(func, ast.Attribute):
            return
        method = getattr(func, "attr", "").lower()
        if method not in ("execute", "executemany", "executescript"):
            return
        if not node.args:
            return
        arg = node.args[0]
        # Case 1: string formatting via % operator inside the call
        if isinstance(arg, ast.BinOp) and isinstance(arg.op, __import__("operator").mod):
            self._maybe_record_formatted(arg, node)
        # Case 2: .format() call as the argument
        elif isinstance(arg, ast.Call) and getattr(arg.func, "attr", "").lower() == "format":
            self._maybe_record_format(arg, node)
        # Case 3: f-string (JoinedStr) with SQL keywords
        elif isinstance(arg, ast.JoinedStr):
            text = ast.unparse(arg)
            if self._is_sql_string(text):
                self._record(node, text)

    def _maybe_record_formatted(self, node, call_node):
        # "SELECT ... %s" % var  OR  "SELECT ..." % {dict}
        if isinstance(node.left, ast.Constant) and isinstance(node.left.value, str):
            if self._is_sql_string(node.left.value):
                self._record(call_node, f"execute({node.left.value!r} % ...)")

    def _maybe_record_format(self, node, call_node):
        if not node.args:
            return
        first = node.args[0]
        if isinstance(first, ast.Constant) and isinstance(first.value, str):
            if self._is_sql_string(first.value):
                self._record(call_node, f"execute({first.value!r}.format(...))")

    def _record(self, node, description):
        self.results.append((self.filename, node.lineno, description))


def find_sqli_sinks(filepath):
    """Scan a Python source file for likely SQL-injection sinks.

    Returns a list of (filename, line_number, snippet) tuples.
    """
    with open(filepath, "r", encoding="utf-8") as f:
        source = f.read()

    try:
        tree = ast.parse(source)
    except SyntaxError as e:
        raise ValueError(f"Cannot parse {filepath}: {e}")

    finder = SQLiSinkFinder()
    finder.filename = filepath
    finder.visit(tree)
    return finder.results


if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else "target.py"
    for fname, line, snippet in find_sqli_sinks(path):
        print(f"{fname}:{line}: {snippet}")
```

**What it detects**

- `"SELECT ... " + user_input` (string concatenation, `BinOp`)
- `"SELECT ... %s" % var` ( `%`-formatting)
- `"SELECT ...".format(user_input)` (`.format()`)
- `f"SELECT ... {user_input}"` (f-strings)
- All passed to cursor `.execute()` / `.executemany()` / `.executescript()`

**Important caveats**

- This is heuristic, not a taint analysis. It flags string-built queries containing SQL keywords; it will produce **false positives** (e.g. building a query from constants) and can miss **false negatives** (queries built via f-strings without keywords, or via libraries it doesn't recognize).
- It only inspects the argument to known `execute`-style calls. Queries constructed in one statement and executed in another are not caught.
- For real security work, prefer a purpose-built tool (Bandit's `B608`/`sqlalchemy` checks, Semgrep SQL rules, or a proper taint-analysis engine) rather than this.

