import random
import string
import traceback
from dataclasses import dataclass, field


@dataclass
class FuzzResult:
    crashing: bool
    input: bytes
    traceback: str | None = None


def run_with_traceback(func, data):
    try:
        func(data)
        return FuzzResult(False, data, None)
    except Exception:
        return FuzzResult(True, data, traceback.format_exc())


class MutationFuzzer:
    def __init__(self, seed: bytes, rng: random.Random | None = None):
        self.seed = bytearray(seed)
        self.rng = rng or random.Random(0x5eed)

    def mutate(self, data: bytes) -> bytes:
        buf = bytearray(data)
        op = self.rng.random()
        n = self.rng.randint(1, 8)

        if op < 0.25:  # insert bytes
            pos = self.rng.randint(0, len(buf))
            buf.insert(pos, self.rng.randint(0, 255))
        elif op < 0.5:  # delete bytes
            if buf:
                for _ in range(n):
                    if buf:
                        del buf[self.rng.randint(0, len(buf) - 1)]
        elif op < 0.75:  # flip bits / randomize bytes
            for _ in range(n):
                if buf:
                    i = self.rng.randint(0, len(buf) - 1)
                    if self.rng.random() < 0.5:
                        buf[i] ^= 1 << self.rng.randint(0, 7)
                    else:
                        buf[i] = self.rng.randint(0, 255)
        else:  # splice in a chunk of printable text
            pos = self.rng.randint(0, len(buf))
            text = ''.join(self.rng.choice(string.printable) for _ in range(n))
            buf = buf[:pos] + text.encode() + buf[pos:]

        return bytes(buf)


def minimise(func, crashing: bytes, *, max_iterations: int = 20000) -> bytes:
    """Reduce a crashing input to a smaller crashing input."""
    best = crashing
    for _ in range(max_iterations):
        changed = False
        # Try deleting each byte.
        for i in range(len(best)):
            candidate = best[:i] + best[i + 1:]
            if run_with_traceback(func, candidate).crashing:
                best = candidate
                changed = True
                break
        if changed:
            continue
        # Try flipping each byte to zero.
        for i in range(len(best)):
            candidate = best[:i] + bytes([0]) + best[i + 1:]
            if run_with_traceback(func, candidate).crashing:
                best = candidate
                changed = True
                break
        if not changed:
            break
    return best


def fuzz(func, seed: bytes, *,
         generations: int = 2000,
         pop_size: int = 64,
         keep: int = 8,
         on_crash=None) -> list[bytes]:
    """
    Genetic-ish loop. `func` should raise on a crash. Returns list of
    minimised crashing inputs. `on_crash(crash_bytes, tb)` if provided gets
    the raw crash before minimisation.
    """
    fuzzer = MutationFuzzer(seed)
    seen = set()
    crashes = []
    pool = [bytearray(seed)]

    for _ in range(generations):
        new_pool = []
        for _ in range(pop_size):
            parent = fuzzer.rng.choice(pool)
            data = fuzzer.mutate(bytes(parent))
            result = run_with_traceback(func, data)
            if result.crashing:
                key = _fingerprint(result.traceback or "")
                if key not in seen:
                    seen.add(key)
                    crashes.append(data)
                    if on_crash:
                        on_crash(data, result.traceback)
            else:
                new_pool.append(bytearray(data))
        if new_pool:
            pool = new_pool[:keep]
        if not pool:
            pool = [bytearray(seed)]

    minimised = [minimise(func, c) for c in crashes]
    # Deduplicate minimised results by content.
    uniq = []
    seen_content = set()
    for m in minimised:
        if m not in seen_content:
            seen_content.add(m)
            uniq.append(m)
    return uniq


def _fingerprint(tb: str) -> str:
    """Collapse a traceback to its essential signature."""
    lines = tb.strip().splitlines()
    # Keep the exception type + last few frames (excluding our internals).
    sig = []
    for line in lines:
        if line.startswith("Traceback") or line.strip() == "":
            continue
        sig.append(line.strip())
    return "\n".join(sig[-4:])
