import ast


def scan_sql_injections(source_code: str):
    """Return list of "file:line" strings where a query string is built via formatting."""
    tree = ast.parse(source_code)
    results = []

    # Common SQL verbs that indicate an executable query.
    sql_keywords = ("SELECT", "INSERT", "UPDATE", "DELETE", "DROP", "CREATE", "ALTER", "GRANT")

    for node in ast.walk(tree):
        # f-strings / .format() / % / + building a SQL string
        if isinstance(node, (ast.JoinedStr, ast.BinOp)):
            value = _extract_value(node)
            if value and any(kw in value.upper() for kw in sql_keywords):
                results.append(f"{node.lineno}")

    return results


def _extract_value(node):
    """Best-effort extraction of a string literal from an f-string/BinOp."""
    try:
        if isinstance(node, ast.JoinedStr):
            parts = []
            for v in node.values:
                if isinstance(v, ast.Constant) and isinstance(v.value, str):
                    parts.append(v.value)
                else:
                    parts.append("{}")  # placeholder for interpolated expr
            return "".join(parts)
        elif isinstance(node, ast.BinOp) and isinstance(node.op, ast.Mod):
            if isinstance(node.left, ast.Constant) and isinstance(node.left.value, str):
                return node.left.value
    except Exception:
        pass
    return None
