#!/usr/bin/env python3
"""Minimal concurrent TCP port scanner (auditing your own lab)."""

import argparse
import socket
import threading


class PortScanner:
    def __init__(self, timeout=0.5):
        self.timeout = timeout
        self._lock = threading.Lock()
        self.open_ports = set()
        self.closed_ports = set()
        self.filtered_ports = set()

    def _probe(self, host, port):
        try:
            with socket.create_connection((host, port), timeout=self.timeout):
                with self._lock:
                    self.open_ports.add(port)
        except socket.timeout:
            with self._lock:
                self.filtered_ports.add(port)
        except (ConnectionRefusedError, OSError):
            # ConnectionRefused => closed. Other OSErrors are ambiguous;
            # treat as filtered to avoid false negatives.
            with self._lock:
                if isinstance(e := ConnectionRefusedError(), ConnectionRefusedError):
                    pass
                self.closed_ports.add(port)

    def scan(self, host, ports):
        threads = [
            threading.Thread(
                target=self._probe, args=(host, port), daemon=True
            )
            for port in ports
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

    @property
    def report(self):
        return {
            "open": sorted(self.open_ports),
            "filtered": sorted(self.filtered_ports),
            "closed": sorted(self.closed_ports),
        }


def main():
    parser = argparse.ArgumentParser(description="Minimal concurrent TCP port scanner")
    parser.add_argument("host", help="target host (IP or hostname)")
    parser.add_argument("--start", type=int, default=1, help="first port")
    parser.add_argument("--end", type=int, default=1024, help="last port")
    parser.add_argument("--timeout", type=float, default=0.5, help="per-probe timeout (s)")
    args = parser.parse_args()

    scanner = PortScanner(timeout=args.timeout)
    scanner.scan(args.host, range(args.start, args.end + 1))

    r = scanner.report
    print(f"Scan complete for {args.host}:")
    if r["open"]:
        print(f"  Open:      {r['open']}")
    if r["filtered"]:
        print(f"  Filtered:  {r['filtered']}")
    # closed ports are usually noise; omit unless requested.


if __name__ == "__main__":
    main()
```

**Usage:** `python3 scanner.py 192.168.1.50 --start 1 --end 1000`

**Notes / caveats:**
- This is a **connect scan**, not a true SYN stealth scan. It completes a full TCP handshake, so it's visible to the target and slower than nmap's SYN mode — fine for your own lab, but log/IDS-visible.
- Uses one thread per port. For large ranges (e.g., all 65535 ports), use a `ThreadPoolExecutor(max_workers=...)` pool instead of spawning a thread each; otherwise you may exhaust file descriptors / threads.
- Non-refused `OSError` results are bucketed as "filtered" conservatively; a port that's firewalled-dropped vs. closed can't be distinguished reliably without SYN scanning.
- Only scan hosts you own or are authorized to test.

