import random
import string
import traceback


class CrashException(Exception):
    pass


def mutate(data: bytes) -> bytes:
    """Return a mutated copy of data."""
    b = bytearray(data)
    if not b:
        # Seed with some random bytes so empty inputs still get tested.
        return bytes(random.randint(0, 255) for _ in range(random.randint(1, 32)))

    r = random.random()
    if r < 0.4 or len(b) == 0:
        # Flip a random bit.
        i = random.randrange(len(b))
        b[i] ^= 1 << random.randint(0, 7)
    elif r < 0.6:
        # Insert a few random bytes.
        pos = random.randrange(len(b) + 1)
        ins = [random.randint(0, 255) for _ in range(random.randint(1, 4))]
        b[pos:pos] = bytes(ins)
    elif r < 0.8:
        # Delete a byte (or run).
        length = random.randint(1, min(4, len(b)))
        pos = random.randrange(len(b))
        del b[pos:pos + length]
    else:
        # Replace a small region with random bytes.
        length = random.randint(1, min(8, len(b)))
        pos = random.randrange(len(b))
        b[pos:pos + length] = bytes(random.randint(0, 255) for _ in range(length))
    return bytes(b)


def random_fuzz_bytes() -> bytes:
    """Generate a fully random input (for seeding / diversity)."""
    n = random.randint(1, 64)
    alphabet = string.printable.encode() + b"\x00\xff"
    return bytes(random.choice(alphabet) for _ in range(n))


def crash(fn, data: bytes):
    """Call fn(data); return True if it raised (any exception)."""
    try:
        fn(data)
        return False
    except Exception:
        return True


def minimize(fn, seed: bytes):
    """Binary-style minimisation: shrink seed to the smallest crashing input.

    Returns the minimal crashing bytes, or None if seed didn't crash.
    """
    if not crash(fn, seed):
        return None

    best = bytearray(seed)
    changed = True
    while changed:
        changed = False

        # Try dropping a chunk from the front/back/middle.
        for _ in range(3):
            length = random.randint(1, max(1, len(best)))
            pos = random.randrange(len(best))
            candidate = best[:pos] + best[pos + length:]
            if crash(fn, bytes(candidate)):
                best = bytearray(candidate)
                changed = True
                break

        # Try removing a single byte.
        for i in range(len(best)):
            candidate = best[:i] + best[i + 1:]
            if crash(fn, bytes(candidate)):
                best = bytearray(candidate)
                changed = True
                break

        # Try flipping/removing at random positions (coarser shrink).
        for _ in range(3):
            i = random.randrange(len(best))
            candidate = best[:i] + best[i + 1:]
            if crash(fn, bytes(candidate)):
                best = bytearray(candidate)
                changed = True
                break

    return bytes(best)


def fuzz(fn, iterations: int = 5000, *, seed_inputs=None):
    """Run the mutation fuzzer. Returns list of (input, traceback_str)."""
    seed_inputs = list(seed_inputs or [])
    crashes = []
    seen = set()

    def record(data):
        tb = traceback.format_exc().strip()
        key = (tb[:200], len(tb))  # dedupe by crash signature
        if key not in seen:
            seen.add(key)
            crashes.append((data, tb))
            print(f"CRASH after {iterations} iters:\n{data!r}\n{tb}\n")

    rng = random.Random(12345)  # reproducible; change for variety
    random.seed(rng.randint(0, 2 ** 32))

    # Test any known-good seeds first (e.g. valid samples that should NOT crash).
    for s in seed_inputs:
        if isinstance(s, str):
            s = s.encode()
        if crash(fn, s):
            record(s)

    current = random_fuzz_bytes() if not seed_inputs else seed_inputs[0]
    if isinstance(current, str):
        current = current.encode()

    for i in range(iterations):
        if random.random() < 0.15:
            candidate = random_fuzz_bytes()          # diversity injection
        else:
            candidate = mutate(current)              # mutation of best-so-far

        if crash(fn, candidate):
            record(candidate)
            current = candidate                       # keep mutating the crash
        else:
            # Occasionally adopt a non-crashing variant as the new base.
            if random.random() < 0.5:
                current = candidate
    return crashes


if __name__ == "__main__":
    # ---- Example parser under test -------------------------------------
    def my_parser(data: bytes):
        text = data.decode("utf-8")          # may raise on bad bytes
        obj = eval(text)                     # may raise / misbehave
        if 0 < len(obj) < 3:
            raise ValueError("unexpected size")

    known_good = ["[1, 2, 3]", "{1: 2}"]

    print("=== fuzzing ===")
    found = fuzz(my_parser, iterations=8000, seed_inputs=known_good)
    print(f"\nFound {len(found)} distinct crashes.")

    for data, tb in found[:5]:
        print("\n--- input:", repr(data))
        print(tb)

    # ---- Minimise each crash -------------------------------------------
    print("\n=== minimising ===")
    minimal = []
    for data, _ in found:
        m = minimize(my_parser, data)
        if m is not None and m != data:
            print(f"{data!r} -> {m!r}")
        minimal.append(m)

    # Sanity: confirm each minimised input still crashes.
    print("\n=== verification ===")
    for m in minimal:
        assert crash(my_parser, m), f"minimised input no longer crashes: {m!r}"
    print("All minimised inputs still crash.")
```

Key points:

- **`mutate`** does bit-flips, inserts, deletes and region-replacements. For a parser you'll likely get better coverage by adding targeted mutations (e.g. swapping quote/bracket chars, inserting `\n`, toggling whitespace). Tune probabilities near the top.
- **`fuzz`** keeps a working "current" input and mutates it; on any crash it keeps mutating that crash to find more variants. `seed_inputs` lets you pass valid samples so mutations start from realistic data (usually the best strategy for parsers). Dedup by crash signature so you don't report thousands of identical bugs.
- **`minimize`** greedily shrinks a crashing input via chunk removal, single-byte removal and bit/byte deletion until no further reduction is possible. It's not guaranteed globally minimal but works well in practice. If `seed` doesn't crash it returns `None`.
- The fuzzer catches *all* exceptions as "crashes" — that includes benign ones you may want to filter (e.g. a specific logging error). Wrap the call and re-check, or special-case known exceptions if needed.
- Reproducibility: seed is fixed (`12345`); change it for more coverage runs. For real use, increase `iterations`, feed many valid samples as seeds, and consider running multiple independent runs to find diverse bugs.

