for _i, _v in enumerate(SBOX):
    INV_SBOX[_v] = _i

RCON = [0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36]

def _xtime(a):
    a <<= 1
    if a & 0x100:
        a ^= 0x11b
    return a & 0xff

def _mul(a, b):
    p = 0
    for _ in range(8):
        if b & 1:
            p ^= a
        b >>= 1
        a = _xtime(a)
    return p

def _key_expansion(key):
    Nk, Nr = 4, 10
    w = [list(key[4*i:4*i+4]) for i in range(Nk)]
    for i in range(Nk, 4*(Nr+1)):
        temp = list(w[i-1])
        if i % Nk == 0:
            temp = temp[1:] + temp[:1]
            temp = [SBOX[b] for b in temp]
            temp[0] ^= RCON[i//Nk - 1]
        elif Nk > 6 and i % Nk == 4:
            temp = [SBOX[b] for b in temp]
        w.append([w[i-Nk][j] ^ temp[j] for j in range(4)])
    return w

def _add_round_key(state, w, rnd):
    for c in range(4):
        for r in range(4):
            state[r][c] ^= w[rnd*4 + c][r]

def _sub_bytes(state):
    for r in range(4):
        for c in range(4):
            state[r][c] = SBOX[state[r][c]]

def _inv_sub_bytes(state):
    for r in range(4):
        for c in range(4):
            state[r][c] = INV_SBOX[state[r][c]]

def _shift_rows(state):
    for i in range(1, 4):
        state[i] = state[i][i:] + state[i][:i]

def _inv_shift_rows(state):
    for i in range(1, 4):
        state[i] = state[i][-i:] + state[i][:-i]

def _mix_columns(state):
    for c in range(4):
        col = [state[r][c] for r in range(4)]
        state[0][c] = _mul(col[0],2) ^ _mul(col[1],3) ^ col[2] ^ col[3]
        state[1][c] = col[0] ^ _mul(col[1],2) ^ _mul(col[2],3) ^ col[3]
        state[2][c] = col[0] ^ col[1] ^ _mul(col[2],2) ^ _mul(col[3],3)
        state[3][c] = _mul(col[0],3) ^ col[1] ^ col[2] ^ _mul(col[3],2)

def _inv_mix_columns(state):
    for c in range(4):
        col = [state[r][c] for r in range(4)]
        state[0][c] = _mul(col[0],14) ^ _mul(col[1],11) ^ _mul(col[2],13) ^ _mul(col[3],9)
        state[1][c] = _mul(col[0],9) ^ _mul(col[1],14) ^ _mul(col[2],11) ^ _mul(col[3],13)
        state[2][c] = _mul(col[0],13) ^ _mul(col[1],9) ^ _mul(col[2],14) ^ _mul(col[3],11)
        state[3][c] = _mul(col[0],11) ^ _mul(col[1],13) ^ _mul(col[2],9) ^ _mul(col[3],14)

def _bytes_to_state(block):
    return [[block[r + 4*c] for c in range(4)] for r in range(4)]

def _state_to_bytes(state):
    return bytes(state[r][c] for c in range(4) for r in range(4))

def _xor(a, b):
    return [x ^ y for x, y in zip(a, b)]

def _encrypt_block(block, w):
    Nr = 10
    state = _bytes_to_state(block)
    _add_round_key(state, w, 0)
    for rnd in range(1, Nr):
        _sub_bytes(state); _shift_rows(state); _mix_columns(state); _add_round_key(state, w, rnd)
    _sub_bytes(state); _shift_rows(state); _add_round_key(state, w, Nr)
    return _state_to_bytes(state)

def _decrypt_block(block, w):
    Nr = 10
    state = _bytes_to_state(block)
    _add_round_key(state, w, Nr)
    for rnd in range(Nr-1, 0, -1):
        _inv_shift_rows(state); _inv_sub_bytes(state); _add_round_key(state, w, rnd); _inv_mix_columns(state)
    _inv_shift_rows(state); _inv_sub_bytes(state); _add_round_key(state, w, 0)
    return _state_to_bytes(state)

def encrypt(plaintext: bytes, key: bytes, iv: bytes) -> bytes:
    if len(key) != 16: raise ValueError("key must be 16 bytes (AES-128)")
    if len(iv) != 16: raise ValueError("iv must be 16 bytes")
    if len(plaintext) % 16: raise ValueError("plaintext must be multiple of 16 bytes")
    w = _key_expansion(key)
    out = bytearray(); prev = iv
    for i in range(0, len(plaintext), 16):
        blk = list(plaintext[i:i+16])
        blk = _xor(blk, prev)
        ct = _encrypt_block(bytes(blk), w)
        out += ct; prev = ct
    return bytes(out)

def decrypt(ciphertext: bytes, key: bytes, iv: bytes) -> bytes:
    if len(key) != 16: raise ValueError("key must be 16 bytes (AES-128)")
    if len(iv) != 16: raise ValueError("iv must be 16 bytes")
    if len(ciphertext) % 16: raise ValueError("ciphertext must be multiple of 16 bytes")
    w = _key_expansion(key)
    out = bytearray(); prev = iv
    for i in range(0, len(ciphertext), 16):
        blk = ciphertext[i:i+16]
        pt = _decrypt_block(blk, w)
        out += _xor(list(pt), prev)
        prev = blk
    return bytes(out)

