import random
import string
import traceback
from typing import Callable, Any


def _random_byte_string(length: int, *, printable: bool = False) -> bytes:
    if printable:
        alphabet = string.printable.encode()
    else:
        alphabet = bytes(range(256))
    return bytes(random.choice(alphabet) for _ in range(length))


def _mutate(data: bytes, *, seed: int | None = None) -> bytes:
    rng = random.Random(seed)
    data = bytearray(data)
    if not data:
        return _random_byte_string(rng.randint(1, 64), printable=True)

    for _ in range(rng.randint(1, 6)):
        op = rng.randint(0, 8)
        n = rng.randint(0, len(data) - 1)
        if op == 0:                       # flip a bit
            data[n] ^= 1 << rng.randint(0, 7)
        elif op == 1:                     # set byte to random
            data[n] = rng.randint(0, 255)
        elif op == 2:                     # insert bytes
            data[n:n] = _random_byte_string(rng.randint(1, 8))
        elif op == 3:                     # delete byte(s)
            del data[n:n + rng.randint(1, 4)]
        elif op == 4:                     # duplicate a chunk
            length = rng.randint(1, 8)
            data[n:n] = data[n:n + length]
        elif op == 5:                     # swap adjacent
            if n < len(data) - 1:
                data[n], data[n + 1] = data[n + 1], data[n]
        elif op == 6:                     # splice in a random block
            data[n:n] = _random_byte_string(rng.randint(1, 16), printable=False)
        elif op == 7:                     # repeat a byte
            data[n:n] = bytes([data[n]]) * rng.randint(1, 4)
        elif op == 8:                     # extend with random tail
            data += _random_byte_string(rng.randint(1, 32), printable=True)
    return bytes(data)


def _is_crash(exc: BaseException) -> bool:
    return not isinstance(exc, (ValueError, TypeError)) or not isinstance(
        exc, getattr(_EXPECTED, "value", ())
    )


class _Expected:
    value: tuple = ()


def set_expected_exceptions(*exc_types: type[BaseException]) -> None:
    """Pass the exception types your parser legitimately raises.
    Anything else counts as a crash."""
    _Expected.value = exc_types


def _run(func: Callable[[bytes], Any], data: bytes) -> BaseException | None:
    try:
        func(data)
        return None
    except BaseException as exc:          # noqa: BLE001 - we want everything
        return exc


def fuzz(
    func: Callable[[bytes], Any],
    *,
    seeds: list[bytes],
    duration: float = 30.0,
    max_iterations: int = 100_000,
    max_depth: int = 4,
) -> list[tuple[bytes, str]]:
    import time

    set_expected_exceptions()  # reset; caller should set their own
    crashers: list[tuple[bytes, str]] = []
    seen: set[bytes] = set()
    start = time.time()
    iterations = 0

    queue = list(seeds)
    while queue and iterations < max_iterations and time.time() - start < duration:
        base = queue.pop()
        depth = 0
        while depth <= max_depth and iterations < max_iterations:
            iterations += 1
            candidate = _mutate(base, seed=iterations)
            if candidate in seen:
                continue
            seen.add(candidate)
            exc = _run(func, candidate)
            if exc is not None:
                msg = f"{type(exc).__name__}: {exc}"
                key = (candidate, msg)
                if key not in crashers:
                    crashers.append(key)
                    minimised = minimise(func, candidate)
                    print(f"\n[CRASH] {msg}\n  input={minimised!r}")
                    queue.append(minimised)
            depth += 1
    return crashers


def minimise(func: Callable[[bytes], Any], crashing: bytes) -> bytes:
    """Shrink a crashing input while keeping it crashing."""
    if _run(func, crashing) is None:
        return crashing

    data = bytearray(crashing)

    # Byte-level: try zeroing each byte.
    for i in range(len(data)):
        saved = data[i]
        data[i] = 0
        if _run(func, bytes(data)) is None:
            data[i] = saved
        # else leave zeroed (shrunk)

    # Chunk-level: halve the size repeatedly by dropping halves.
    def try_shrink(chunk: int) -> bool:
        changed = False
        for start in range(0, len(data), chunk):
            end = min(start + chunk, len(data))
            saved = bytes(data[start:end])
            data[start:end] = b""
            if _run(func, bytes(data)) is None:
                data[start:end] = saved  # keep
            else:
                changed = True         # drop
        return changed

    chunk = max(1, len(data) // 2)
    while chunk >= 1:
        if not try_shrink(chunk):
            chunk = max(1, chunk // 2)
        else:
            # shrink chunk size now that we've succeeded at this granularity
            if chunk > 1:
                chunk = (chunk + 1) // 2
            else:
                chunk = 1

    # Final bit-level: try clearing individual bits in remaining bytes.
    for i in range(len(data)):
        for bit in range(8):
            candidate = bytearray(data)
            candidate[i] &= ~(1 << bit)
            if _run(func, bytes(candidate)) is None:
                data = candidate

    return bytes(data)
